/**
 * @file Vmf3.cpp
 * @brief Implementation of the VMF3 mapping function (empirical, from GPT3).
 *
 * Line-for-line port of the TU Wien reference @c vmf3.m (Landskron & Boehm
 * 2018): the Legendre recursion, the spherical-harmonic synthesis loop, the
 * seasonal harmonic evaluation and the Marini continued fraction follow the
 * MATLAB source.  The 91 × 5 coefficient arrays are in
 * @c Vmf3Coefficients.hpp, generated by scripts/extract_vmf3_coeffs.py from
 * vmf3.m.
 */

#include "atmosphere/Vmf3.hpp"
#include "atmosphere/Vmf3Coefficients.hpp"
#include "common/Constants.hpp"

#include <cmath>

namespace GnssProcessor {

    namespace {
        constexpr int N_MAX = 12;
        constexpr int DIM   = N_MAX + 1;     // V/W tables are (N_MAX+1) × (N_MAX+1)
        constexpr int N_TERMS = 91;          // sum_{n=0..12} (n+1)

        // Evaluate the 5-coefficient annual + semi-annual harmonic at doy:
        //   V = A0 + A1 cos(ω) + B1 sin(ω) + A2 cos(2ω) + B2 sin(2ω)
        // where ω = 2π * doy / 365.25.
        inline double evalSeasonal(double A0, double A1, double B1, double A2, double B2,
                                   double c1, double s1, double c2, double s2) {
            return A0 + A1 * c1 + B1 * s1 + A2 * c2 + B2 * s2;
        }
    } // namespace

    void Vmf3::computeMapping(double lat_rad, double lon_rad, double doy,
                              double elevation_rad, double a_h, double a_w,
                              double& mf_d, double& mf_w) {
        // --- Legendre table init.  V/W are indexed as MATLAB's V(n+1, m+1). ---
        const double polDist = Constants::PI * 0.5 - lat_rad;
        const double sinPol  = std::sin(polDist);
        const double cosPol  = std::cos(polDist);
        const double x = sinPol * std::cos(lon_rad);
        const double y = sinPol * std::sin(lon_rad);
        const double z = cosPol;

        double V[DIM + 1][DIM + 1] = {};
        double W[DIM + 1][DIM + 1] = {};
        V[1][1] = 1.0;
        W[1][1] = 0.0;
        V[2][1] = z * V[1][1];
        W[2][1] = 0.0;

        // Zonal terms (m = 0): V(n+1,1), W(n+1,1) = 0 by construction.
        for (int n = 2; n <= N_MAX; ++n) {
            V[n + 1][1] = ((2 * n - 1) * z * V[n][1] - (n - 1) * V[n - 1][1]) / n;
            W[n + 1][1] = 0.0;
        }
        // Tesseral / sectoral terms (m >= 1).
        for (int m = 1; m <= N_MAX; ++m) {
            V[m + 1][m + 1] = (2 * m - 1) * (x * V[m][m] - y * W[m][m]);
            W[m + 1][m + 1] = (2 * m - 1) * (x * W[m][m] + y * V[m][m]);
            if (m < N_MAX) {
                V[m + 2][m + 1] = (2 * m + 1) * z * V[m + 1][m + 1];
                W[m + 2][m + 1] = (2 * m + 1) * z * W[m + 1][m + 1];
            }
            for (int n = m + 2; n <= N_MAX; ++n) {
                V[n + 1][m + 1] =
                    ((2 * n - 1) * z * V[n][m + 1] - (n + m - 1) * V[n - 1][m + 1]) / (n - m);
                W[n + 1][m + 1] =
                    ((2 * n - 1) * z * W[n][m + 1] - (n + m - 1) * W[n - 1][m + 1]) / (n - m);
            }
        }

        // --- Spherical-harmonic synthesis of the b/c seasonal coefficients. ---
        // The 91 (n, m) pairs are iterated in the order n=0..12, m=0..n, the
        // order used when generating Vmf3Coefficients.hpp.
        double bh[5] = {}, bw[5] = {}, ch[5] = {}, cw[5] = {};

        int idx = 0;
        for (int n = 0; n <= N_MAX; ++n) {
            for (int m = 0; m <= n; ++m) {
                const double Vnm = V[n + 1][m + 1];
                const double Wnm = W[n + 1][m + 1];
                for (int k = 0; k < 5; ++k) {
                    bh[k] += Vmf3Coeffs::anm_bh[idx][k] * Vnm + Vmf3Coeffs::bnm_bh[idx][k] * Wnm;
                    bw[k] += Vmf3Coeffs::anm_bw[idx][k] * Vnm + Vmf3Coeffs::bnm_bw[idx][k] * Wnm;
                    ch[k] += Vmf3Coeffs::anm_ch[idx][k] * Vnm + Vmf3Coeffs::bnm_ch[idx][k] * Wnm;
                    cw[k] += Vmf3Coeffs::anm_cw[idx][k] * Vnm + Vmf3Coeffs::bnm_cw[idx][k] * Wnm;
                }
                ++idx;
            }
        }
        // N_TERMS records the table length (idx ends at 91); nothing asserts it,
        // and the cast only suppresses the unused-constant warning.
        (void)N_TERMS;

        // --- Seasonal evaluation at the requested DOY. ---
        const double omega = 2.0 * Constants::PI * doy / 365.25;
        const double c1 = std::cos(omega);
        const double s1 = std::sin(omega);
        const double c2 = std::cos(2.0 * omega);
        const double s2 = std::sin(2.0 * omega);

        const double bh_val = evalSeasonal(bh[0], bh[1], bh[2], bh[3], bh[4], c1, s1, c2, s2);
        const double bw_val = evalSeasonal(bw[0], bw[1], bw[2], bw[3], bw[4], c1, s1, c2, s2);
        const double ch_val = evalSeasonal(ch[0], ch[1], ch[2], ch[3], ch[4], c1, s1, c2, s2);
        const double cw_val = evalSeasonal(cw[0], cw[1], cw[2], cw[3], cw[4], c1, s1, c2, s2);

        // --- Marini continued fraction. ---
        const double sinEl = std::sin(elevation_rad);
        const double numer_d = 1.0 + a_h / (1.0 + bh_val / (1.0 + ch_val));
        const double denom_d = sinEl + a_h / (sinEl + bh_val / (sinEl + ch_val));
        const double numer_w = 1.0 + a_w / (1.0 + bw_val / (1.0 + cw_val));
        const double denom_w = sinEl + a_w / (sinEl + bw_val / (sinEl + cw_val));

        mf_d = (std::abs(denom_d) > 1e-12) ? numer_d / denom_d : 1.0;
        mf_w = (std::abs(denom_w) > 1e-12) ? numer_w / denom_w : 1.0;
    }

} // namespace GnssProcessor
